(function() {
	const base64_B = "data:image/png;base64,";
	const base64_BL = "data:image/png;base64,";
	const base64_BL2 = "data:image/png;base64,";
	const base64_BR = "data:image/png;base64,";
	const base64_BR2 = "data:image/png;base64,";
	const base64_L = "data:image/png;base64,";
	const base64_R = "data:image/png;base64,";
	const base64_T = "data:image/png;base64,";
	const base64_TL = "data:image/png;base64,";
	const base64_TL2 = "data:image/png;base64,";
	const base64_TR = "data:image/png;base64,";
	const base64_TR2 = "data:image/png;base64,";

	const base64_mochihead = "data:image/png;base64,";
	const base64_mochiheaddead = "data:image/png;base64,";
	const base64_mochiback = "data:image/png;base64,";
	const base64_bone = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAADAAAAAwAQMAAABtzGvEAAAAAXNSR0IB2cksfwAAAAlwSFlzAAALEwAACxMBAJqcGAAAAAZQTFRFAAAAAAAApWe5zwAAAAJ0Uk5TAP9bkSK1AAAAMUlEQVR4nGNgoB1g/MPAwP8AjeL/38BQ/weDAgJ0ihFEPcBOYdWA1WisjgABKEVlAABE7lBMxnDpuwAAAABJRU5ErkJggg==";



	const base64_sndCrunch = "";
	const base64_sndBark = "";

	const canvas = document.getElementById('snakeCanvas');
	const ctx = canvas.getContext('2d');



	const border = 20;
	const tileSize = 48;

	const gameW = 20;
	const gameH = 11;

	const gameOffset = tileSize / 2 + 20;

	const refreshTime = 300;

	// Logique de jeu ici

	const windowMochigame = document.getElementById("window-mochigame");

	const buttonStart = document.getElementById("snake-button-start");
	const arrowLeft = document.getElementById("snake-arrow-left");
	const arrowRight = document.getElementById("snake-arrow-right");
	const arrowUp = document.getElementById("snake-arrow-up");
	const arrowDown = document.getElementById("snake-arrow-down");
	const divTime = document.getElementById("snake-time");
	const divLives = document.getElementById("snake-lives");
	const divScore = document.getElementById("snake-score");
	const divHeart1 = document.getElementById("snake-heart1");
	const divHeart2 = document.getElementById("snake-heart2");
	const divHeart3 = document.getElementById("snake-heart3");
	const divScreenIntro = document.getElementById("snake-intro");
	const divScreenGameover = document.getElementById("snake-gameover");

	const snakeMainbg = document.getElementById("snake-mainbg");
	const snakeBone = document.getElementById("snake-bone");
	const snakeBoneGreen = document.getElementById("snake-bone-green");
	const snakeHeartsGreen = document.getElementById("mochi-hearts-green");





	class MainScene extends Phaser.Scene {
		constructor() {
			super('MainScene');
		}

		
		preload() 
		{

			console.log("preload");
			// preload assets
			this.textures.addBase64('B',                base64_B);
			this.textures.addBase64('BL',               base64_BL);
			this.textures.addBase64('BR',               base64_BR);
			this.textures.addBase64('L',                base64_L);
			this.textures.addBase64('R',                base64_R);
			this.textures.addBase64('T',                base64_T);
			this.textures.addBase64('TL',               base64_TL);
			this.textures.addBase64('TR',               base64_TR);
			this.textures.addBase64('BL2',              base64_BL2);
			this.textures.addBase64('BR2',              base64_BR2);
			this.textures.addBase64('TL2',              base64_TL2);
			this.textures.addBase64('TR2',              base64_TR2);
			this.textures.addBase64('mochi-head',       base64_mochihead);
			this.textures.addBase64('mochi-head-dead',  base64_mochiheaddead);
			this.textures.addBase64('mochi-back',       base64_mochiback);
			this.textures.addBase64('bone',             base64_bone);
			
			this.sound.on('decoded', (sound) => {
				console.log("sounds decoded", sound);
				if(sound == "crunch")
					this.sndCrunch = this.sound.add('crunch');
				if(sound == "bark")
					this.sndBark = this.sound.add('bark');
			});
			this.sound.decodeAudio('crunch', base64_sndCrunch);
			this.sound.decodeAudio('bark', base64_sndBark);
			//
		}	

		_up()
		{        
			if(!this.running)
				return;
			if(this.direction.y == 0)
				this.nextDirection = {x:0, y:-1};
			this.waitForUser = false;
		}
		_down()
		{
			if(!this.running)
				return;
			if(this.direction.y == 0)
				this.nextDirection = {x:0, y:1};
			this.waitForUser = false;
		}
		_left()
		{
			if(!this.running)
				return;
			if(this.waitForUser)
				return;
			if(this.direction.x == 0)
				this.nextDirection = {x:-1, y:0};
		}
		_right()
		{
			if(!this.running)
				return;
			if(this.direction.x == 0)
				this.nextDirection = {x:1, y:0};
			this.waitForUser = false;
		}

		create() 
		{
			console.log("create");
			

			this.cameras.main.setBackgroundColor('#00ff01');
			
			this.input.keyboard.on('keydown-LEFT', () => {
				this._left();
			});
			this.input.keyboard.on('keydown-RIGHT', () => {
				this._right();
			});
			this.input.keyboard.on('keydown-UP', () => {
				this._up();
			});
			this.input.keyboard.on('keydown-DOWN', () => {
				this._down();
			}); 

			buttonStart.addEventListener("click", () => {
				this._clearTiles();
				if(this.boneSprite)
					this.boneSprite.destroy();
				this._init();
			}) 
			arrowLeft.addEventListener("click", () => {
				this._left();
			}) 
			arrowRight.addEventListener("click", () => {
				this._right();
			}) 
			arrowUp.addEventListener("click", () => {
				this._up();
			}) 
			arrowDown.addEventListener("click", () => {
				this._down();
			}) 


			// borders
			var grphBorders = this.add.graphics();
			grphBorders.lineStyle(3, 0x000000, 1);
			grphBorders.beginPath();
			grphBorders.moveTo(border, border); 
			grphBorders.lineTo(border + gameW * tileSize, border); 
			grphBorders.lineTo(border + gameW * tileSize, border + gameH * tileSize); 
			grphBorders.lineTo(border, border + gameH * tileSize); 
			grphBorders.lineTo(border, border); 
			grphBorders.strokePath();
			

	 
		}

		update() 
		{
			if (game.sound.context.state === 'suspended') {
				game.sound.context.resume();
			}

			if(!this.running)
				return;

			this._refreshTime();
			this._refreshLives();
			this._refreshScore();
			

			if (this.time.now < this.nextTick) 
				return;
			
			this.nextTick = this.time.now + refreshTime; // Réexécuter le code après 1000 ms (1 seconde)

			if(!this.dead)
			{
				var looseOneLife = this._refreshSnake();        
				if(!looseOneLife)
				{
					this.positions = this._getSnakePartPositions();
				}       
			}
			this._refreshDisplay(); 
		}

		_init()
		{

			console.log("init");

			this.cameras.main.setBackgroundColor('#00ff01');
			_refreshCssNormal();
			divScreenIntro.style.opacity = "0";
			divScreenGameover.style.opacity = "0";
			
			this.points = 0;
			this.lives = 3;
			this.hasReachedBone = false;
			this.dead = false;
	   
			this.timeAtStart = new Date();

			this._restart();
		}

		_restart()
		{
			this.dead = false;
			this.nextTick = this.time.now + refreshTime;   
			this.running = true;
			this.bonePosition = {x:0, y:0};
			this.direction = {x:0, y:0};
			this.nextDirection = {x:0, y:0};
			this.snake = ["L", "L"];
			this.snakePos = {x: 10, y: 5};
			this.tiles = [];
			this.bonePosition.visible = true;

			this.positions = this._getSnakePartPositions();
			this._popBone();

			this.waitForUser = true;
		}

		_gameOver()
		{
			console.log("gameover");
			
			this.cameras.main.setBackgroundColor('#000000');
			_refreshCssGameover();
			divScreenIntro.style.opacity = "0";
			divScreenGameover.style.opacity = "100";
			this._refreshLives();
			this._clearTiles();
			this.boneSprite.visible = false;
			this.running = false;
		}

		_loseOneLife()
		{
			this.sndBark.play();
			$(windowMochigame).effect( "shake", {times:2, distance:10, direction:"left"}, 200  );		
			this.dead = true;
			this.lives -= 1;
			setTimeout(() => 
			{
				if(this.lives > 0)
				{
					this._clearTiles();
					this._restart();
				}else{
					this._gameOver();
				}
			}, 3000);

		}

		_clearTiles()
		{
			for(const i in this.tiles)
			{
				this.tiles[i].destroy();
			}
			this.tiles = [];
		}

		_refreshTime()
		{
			const now = new Date();
			const elapsedTime = now - this.timeAtStart;
			const diff = new Date(elapsedTime);
			var minutes = diff.getMinutes();
			var seconds = diff.getSeconds();
			minutes = (minutes < 10) ? "0" + minutes : minutes;
			seconds = (seconds < 10) ? "0" + seconds : seconds;
			const timeText = minutes + ":" + seconds;

			divTime.innerText = timeText;
		}
		_refreshLives()
		{
			var livesString = "0" + this.lives.toString();
			divLives.innerText = livesString;
			divHeart1.style.opacity = this.lives >= 3 ? "100" : "0";
			divHeart2.style.opacity = this.lives >= 2 ? "100" : "0";
			divHeart3.style.opacity = this.lives >= 1 ? "100" : "0";
		}
		_refreshScore()
		{
			var scoreString = this.points.toString();
			while(scoreString.length < 3)
				scoreString = "0" + scoreString;
			divScore.innerText = scoreString;
		}

		_popBone()
		{
			var ok = false;
			while(!ok)
			{
				this.bonePosition = {x:Math.floor(Math.random() * gameW), y:Math.floor(Math.random() * gameH)};
				ok = true;
				for(var i in this.positions)
				{
					if(this.positions[i].x == this.bonePosition.x && this.positions[i].y == this.bonePosition.y)
					{
						ok = false;
						break;
					}
				}
			}

		}

		_refreshSnake()
		{
			var looseOnLife = false;

			this.direction = this.nextDirection;
			if(this.direction.x == 0 && this.direction.y == 0)
				return;
			
			
			var snakePosx = this.snakePos.x + this.direction.x;
			var snakePosy = this.snakePos.y + this.direction.y;
			
			// HIT WALL ?
			if(snakePosx < 0 || snakePosx >= gameW || snakePosy < 0 || snakePosy >= gameH)
			{
				this._loseOneLife();          
				return true; 
			}

			// HIT SELF ?
			if(! looseOnLife && this._isPointInPositions({x:snakePosx, y:snakePosy}))
			{
				this._loseOneLife();       
				return true; 
			}



			this.snakePos.x += this.direction.x;
			this.snakePos.y += this.direction.y;

			if(this.direction.x == 1)
			{
				this.snake.unshift("L");
			}    
			if(this.direction.x == -1)
			{
				this.snake.unshift("R");
			}    
			if(this.direction.y == 1)
			{
				this.snake.unshift("T");
			}    
			if(this.direction.y == -1)
			{
				this.snake.unshift("B");
			}   
			
			// Reached Bone ?
			this.hasReachedBone = false;
			if(this.snakePos.x == this.bonePosition.x && this.snakePos.y == this.bonePosition.y)
			{
				this.hasReachedBone = true;
				this.points += 1;
				this.sndCrunch.play();
				this._popBone();
			}
			
			// POP
			if(!this.hasReachedBone)
				this.snake.pop();


			

		
			
			return looseOnLife;
		}

		_isPointInPositions(point)
		{
			for(var i in this.positions)
			{
				if(this.positions[i].x == point.x && this.positions[i].y == point.y)           
					return true;           
			}
			return false;
		}

		_refreshDisplay()
		{
			// bone
			if(this.boneSprite != null)
				this.boneSprite.destroy();
			this.boneSprite = this.add.sprite(tileSize, tileSize, "bone");
			this.boneSprite.x = gameOffset + this.bonePosition.x * tileSize;
			this.boneSprite.y = gameOffset + this.bonePosition.y * tileSize;

			this._clearTiles();
			
			
			for(const i in this.snake)
			{
				const sprite = this._getSpriteForSnake(i);
				sprite.x = gameOffset + this.positions[i].x * tileSize;
				sprite.y = gameOffset + this.positions[i].y * tileSize;
				this.tiles.push(sprite);
			}      
			
			this.tiles[0].visible = false;
			
			// head
			var headSprite = this.dead ? "mochi-head-dead" : "mochi-head";
			var spriteHead = this.add.sprite(200, 200, headSprite);
			spriteHead.setOrigin(0.5, 0.5);
			spriteHead.id = "head";
			this.tiles.push(spriteHead);
			spriteHead.x = gameOffset + this.positions[0].x * tileSize;
			spriteHead.y = gameOffset + this.positions[0].y * tileSize;
			switch(this.snake[0])
			{
				case "R":
					spriteHead.angle = 180;
				break;
				case "T":
					spriteHead.angle = 90;
				break;
				case "B":
					spriteHead.angle = -90;
				break;
			}
			

			// back
			var spriteBack = this.add.sprite(200, 200, "mochi-back");
			spriteBack.setOrigin(0.5, 0.5);
			this.tiles.push(spriteBack);
			spriteBack.x = gameOffset + this.positions[this.positions.length-1].x * tileSize;
			spriteBack.y = gameOffset + this.positions[this.positions.length-1].y * tileSize;
			switch(this.snake[this.snake.length-1])
			{
				case "R":
					spriteBack.angle = 180;
				break;
				case "T":
					spriteBack.angle = 90;
				break;
				case "B":
					spriteBack.angle = -90;
				break;
			}
		}

		_getSnakePartPositions()
		{
			var result = [];
			var pos = {...this.snakePos};
			result.push(pos);
			for(var i = 1; i < this.snake.length; i++)
			{
				pos = {...pos};
				switch(this.snake[i-1])
				{
					case "L":
						pos.x --;
					break;
					case "R":
						pos.x ++;
					break;
					case "T":
						pos.y--;
					break;
					case "B":
						pos.y++;
					break;
					case "TL":
						pos.y --;
						pos.x --;
					break;
					case "BL":
						pos.y ++;
						pos.x --;
					break;
					case "TR":
						pos.y --;
						pos.x ++;
					break;
					case "BR":
						pos.y --;
						pos.x ++;
					break;
				}
				result.push(pos);
			}  
			return result;

		}

		_getSpriteForSnake(snakeIndex)
		{
			const currDir = this.snake[snakeIndex];
			if(snakeIndex == 0)
				return this.add.sprite(tileSize, tileSize, currDir);

			var nextdir = "";
			const prevDir = this.snake[snakeIndex-1];
			switch(prevDir)
			{
				case "L":
					switch(currDir)
					{
						case "L":
							nextdir = "L";
						break;
						case "B":
							nextdir = "TL";
						break;
						case "T":
							nextdir = "BL2";
						break;
					}
				break;
				case "R":
					switch(currDir)
					{
						case "R":
							nextdir = "R";
						break;
						case "T":
							nextdir = "BR";
						break;
						case "B":
							nextdir = "TR2";
						break;
					}
				break;
				case "B":
					switch(currDir)
					{
						case "B":
							nextdir = "B";
						break;
						case "L":
							nextdir = "BR2"; //
						break;
						case "R":
							nextdir = "BL"; ////
						break;
					}
				break;
				case "T":
					switch(currDir)
					{
						case "T":
							nextdir = "T";
						break;
						case "L":
							nextdir = "TR"; //
						break;
						case "R":
							nextdir = "TL2";  ////
						 break;
					}
				break;
			}
			return this.add.sprite(tileSize, tileSize, nextdir);
			
		}

	}

	const config = {
		type: Phaser.CANVAS,
		mode: Phaser.Scale.NONE,
		canvas: canvas,
		width: 1000,
		height: 568,
		zoom: 0.7,
		scene: [MainScene]
	};


	function _refreshCssNormal()
	{
		snakeMainbg.style.backgroundColor = "#00ff01";
		snakeMainbg.style.color = "#000000";
		snakeBone.style.opacity = "100";
		snakeBoneGreen.style.opacity = "0";
		snakeHeartsGreen.style.opacity = "0";
	}
	function _refreshCssGameover()
	{
		snakeMainbg.style.backgroundColor = "#000000";
		snakeMainbg.style.color = "#00ff01";
		snakeBone.style.opacity = "0";
		snakeBoneGreen.style.opacity = "100";
		snakeHeartsGreen.style.opacity = "100";
		
	}

	divScreenIntro.style.opacity = "100";
	divScreenGameover.style.opacity = "0";
	_refreshCssNormal();

	const game = new Phaser.Game(config);
	
})();